import rich.traceback
import sys

rich.traceback.install(show_locals=True)

def cause_recursion():
    root = []
    curr = root
    for _ in range(2000):
        new_list = []
        curr.append(new_list)
        curr = new_list
    return root

def recurse(n, data):
    if n == 0:
        return data
    return recurse(n - 1, data)

if __name__ == "__main__":
    data = cause_recursion()
    recurse(2000, data)

